  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price for a booking made by the given customer at the specified booking time, applying a 20 percent discount when the customer has a membership package containing the DISCOUNTS award and the booking is made at least 24 hours before the trip's departure time.
   * Algorithm:
   *   1. If customer == null OR customer.membershipPackage == null OR bookingTime == null OR departureTime == null, return price (rounded to one decimal place).
   *   2. Parse bookingTime and departureTime as datetime strings in format "yyyy-MM-dd HH:mm"; if parsing fails, return price (rounded to one decimal place).
   *   3. Compute duration = departureTime - bookingTime (in hours/minutes).
   *   4. If duration < 24 hours (strictly less than 24 hours), return price (rounded to one decimal place).
   *   5. If customer.membershipPackage.hasAward(Award.DISCOUNTS) is true, return round(price * 0.8, 1 decimal place); otherwise return price (rounded to one decimal place).
   * Related Features: price, departureTime
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   *   - customer : Customer — the customer making the booking; used to check membership and DISCOUNTS award.
   *   - bookingTime : String — the booking datetime in format "yyyy-MM-dd HH:mm".
   * Output: double — the final price after discount evaluation, kept to one decimal place; returns the original price (rounded to one decimal place) if any input is invalid or the discount condition is not met.
   * Pre-condition: customer and bookingTime are non-null; departureTime is a valid datetime string in "yyyy-MM-dd HH:mm" format.
   * Post-condition: No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    double roundedPrice = new BigDecimal(getPrice()).setScale(1, RoundingMode.HALF_UP).doubleValue();
    if (customer == null || customer.getMembershipPackage() == null || bookingTime == null || getDepartureTime() == null)
    {
      return roundedPrice;
    }
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
    sdf.setLenient(false);
    try
    {
      Date parsedBookingTime = sdf.parse(bookingTime);
      Date parsedDepartureTime = sdf.parse(getDepartureTime());
      long durationMillis = parsedDepartureTime.getTime() - parsedBookingTime.getTime();
      long durationHours = durationMillis / (60L * 60L * 1000L);
      if (durationHours < 24L)
      {
        return roundedPrice;
      }
      if (customer.getMembershipPackage().hasAward(Award.DISCOUNTS))
      {
        return new BigDecimal(getPrice() * 0.8).setScale(1, RoundingMode.HALF_UP).doubleValue();
      }
      return roundedPrice;
    }
    catch (ParseException e)
    {
      return roundedPrice;
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes the total reward points earned by the given customer from all bookings on this trip during the specified month (5 points per booked seat).
   * Algorithm:
   *   1. If customer == null OR customer.membershipPackage == null, return 0.
   *   2. If customer.membershipPackage.hasAward(Award.POINTS) is false, return 0.
   *   3. Initialize totalPoints = 0.
   *   4. For each booking b in this trip's bookings:
   *        a. If b.customer == customer AND b.isInMonth(currentMonth) is true, add (b.numberOfSeats * 5) to totalPoints.
   *   5. Return totalPoints.
   * Related Features: bookings
   * Related Classes: Booking, Customer, MembershipPackage, Award
   * Input:
   *   - customer : Customer — the customer whose points are being computed.
   *   - currentMonth : String — the target month in the format "yyyy-MM".
   * Output: int — total reward points earned by the customer on this trip within the given month (5 points per booked seat); 0 if the customer is not eligible or has no qualifying bookings.
   * Pre-condition: customer is non-null and has a membership package; currentMonth is a non-null string in "yyyy-MM" format.
   * Post-condition: No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null)
    {
      return 0;
    }
    if (!customer.getMembershipPackage().hasAward(Award.POINTS))
    {
      return 0;
    }
    int totalPoints = 0;
    EList<Booking> tripBookings = getBookings();
    if (tripBookings != null)
    {
      for (Booking b : tripBookings)
      {
        if (b.getCustomer() == customer && b.isInMonth(currentMonth))
        {
          totalPoints += b.getNumberOfSeats() * 5;
        }
      }
    }
    return totalPoints;
  }

